{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.journey_reports_summary AS ( WITH journey_base AS ( SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, j.journey_name, TRY_TO_NUMBER(j.node_id) AS node_id, j.node_type, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_start_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_start_time, \'MON DD, HH24:MI\') )::DATE AS start_date, CASE WHEN j.journey_end_time ILIKE \'%never%\' OR j.journey_end_time IS NULL OR TRIM(j.journey_end_time) = \'\' THEN NULL ELSE COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_end_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_end_time, \'MON DD, HH24:MI\') )::DATE END AS end_date, COALESCE(SUM(TRY_TO_NUMBER(j.total_sent)),0) AS total_sents, COALESCE(SUM(TRY_TO_NUMBER(j.total_delivered)),0) AS total_delivered, COALESCE(SUM(TRY_TO_NUMBER(j.total_viewed)),0) AS total_views, COALESCE(SUM(TRY_TO_NUMBER(j.total_clicked)),0) AS total_clicks, j.journey_status, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\')) AS run_date FROM snitch_db.maplemonk.ct_journey_reports j WHERE TRY_TO_NUMBER(j.journey_id) IN (350,348,349,356,336,291,308,309,310,311,312,332,327,337,316) GROUP BY 1,2,3,4,5,6,7,12,13 UNION ALL SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, j.journey_name, TRY_TO_NUMBER(j.node_id) AS node_id, j.node_type, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_start_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_start_time, \'MON DD, HH24:MI\') )::DATE AS start_date, CASE WHEN j.journey_end_time ILIKE \'%never%\' OR j.journey_end_time IS NULL OR TRIM(j.journey_end_time) = \'\' THEN NULL ELSE COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_end_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_end_time, \'MON DD, HH24:MI\') )::DATE END AS end_date, COALESCE(SUM(TRY_TO_NUMBER(j.total_sent)),0) AS total_sents, COALESCE(SUM(TRY_TO_NUMBER(j.total_delivered)),0) AS total_delivered, COALESCE(SUM(TRY_TO_NUMBER(j.total_viewed)),0) AS total_views, COALESCE(SUM(TRY_TO_NUMBER(j.total_clicked)),0) AS total_clicks, j.version_status AS journey_status, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\'),TRY_TO_DATE(j.upload_date,\'YYYY-MM-DD\')) AS run_date FROM snitch_db.maplemonk.ct_journey_reports_1 j WHERE TRY_TO_NUMBER(j.journey_id) IN (350,348,349,356,336,291,308,309,310,311,312,332,327,337,316) GROUP BY 1,2,3,4,5,6,7,12,13 ), journey_campaign AS ( SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, TRY_TO_NUMBER(j.node_id) AS node_id, TRY_TO_NUMBER(TRIM(tok.value)) AS campaign_id, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\'),TRY_TO_DATE(j.upload_date,\'YYYY-MM-DD\')) AS run_date FROM snitch_db.maplemonk.ct_journey_reports j, TABLE(SPLIT_TO_TABLE(REGEXP_REPLACE(j.campaign_segment_controller_id, \'\\s*\\|\\s*\', \',\'), \',\')) tok WHERE TRY_TO_NUMBER(TRIM(tok.value)) IS NOT NULL UNION ALL SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, TRY_TO_NUMBER(j.node_id) AS node_id, TRY_TO_NUMBER(TRIM(tok.value)) AS campaign_id, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\'),TRY_TO_DATE(j.upload_date,\'YYYY-MM-DD\')) AS run_date FROM snitch_db.maplemonk.ct_journey_reports_1 j, TABLE(SPLIT_TO_TABLE(REGEXP_REPLACE(j.campaign_segment_controller_id, \'\\s*\\|\\s*\', \',\'), \',\')) tok WHERE TRY_TO_NUMBER(TRIM(tok.value)) IS NOT NULL ), clicks_charges AS ( SELECT TRY_TO_NUMBER(C_ID) AS campaign_id, CASE WHEN LOWER(CAMPAIGN_CHANNEL) = \'push\' THEN \'Push Notification\' ELSE CAMPAIGN_CHANNEL END AS channel, CLICK_DATE AS click_date, ORDER_NAME, TOTAL_SALES FROM snitch_db.maplemonk.ct_click_charge WHERE LENGTH(C_ID) IN (4,5) ), charges_attributed AS ( SELECT jc.journey_id, jc.node_id, jc.campaign_id, jc.channel, jc.run_date, cc.order_name, cc.total_sales FROM journey_campaign jc JOIN clicks_charges cc ON cc.campaign_id = jc.campaign_id AND (cc.channel = jc.channel OR jc.channel IS NULL) AND cc.click_date = jc.run_date ), journey_click_summary AS ( SELECT journey_id, node_id, channel, run_date, COUNT(DISTINCT order_name) AS total_orders, SUM(total_sales) AS attributed_revenue FROM charges_attributed GROUP BY 1,2,3,4 ) SELECT j.journey_id, j.journey_name, j.node_id, j.channel, j.start_date, j.run_date, j.total_sents, j.total_delivered, j.total_views, j.total_clicks, j.journey_status, ROUND( CASE WHEN j.channel = \'Push Notification\' THEN j.total_clicks/NULLIF(j.total_sents,0) WHEN j.channel = \'Sms\' THEN j.total_clicks/NULLIF(j.total_sents,0) WHEN j.channel = \'WhatsApp\' THEN j.total_clicks/NULLIF(j.total_views,0) WHEN j.channel = \'Email\' THEN j.total_clicks/NULLIF(j.total_sents,0) ELSE 0 END, 2 ) AS CTR, COALESCE(ca.total_orders, 0) AS total_orders, COALESCE(ca.attributed_revenue, 0) AS attributed_revenue, CASE WHEN j.channel = \'Push Notification\' THEN 0 WHEN j.channel = \'Sms\' THEN j.total_delivered * 0.10 WHEN j.channel = \'WhatsApp\' THEN j.total_delivered * 0.71 WHEN j.channel = \'Email\' THEN j.total_delivered * 0.015 ELSE 0 END AS spends, ROUND( COALESCE(ca.attributed_revenue, 0) / NULLIF( CASE WHEN j.channel = \'Push Notification\' THEN 0 WHEN j.channel = \'Sms\' THEN j.total_delivered * 0.10 WHEN j.channel = \'WhatsApp\' THEN j.total_delivered * 0.71 WHEN j.channel = \'Email\' THEN j.total_delivered * 0.015 ELSE 0 END, 0 ), 2 ) AS ROAS FROM journey_base j LEFT JOIN journey_click_summary ca ON j.journey_id = ca.journey_id AND j.node_id = ca.node_id AND j.channel = ca.channel AND j.run_date = ca.run_date ORDER BY j.journey_id, j.node_id, j.channel, j.start_date ); CREATE OR REPLACE TABLE snitch_db.maplemonk.daily_retention_revenue AS ( WITH CTE AS ( SELECT order_timestamp::date AS run_date, SUM(gross_sales) as revenue FROM snitch_db.maplemonk.fact_items_snitch WHERE order_timestamp::date >= \'2025-03-01\' GROUP BY 1 ), push_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As Push_camp_rev, SUM(Spends) AS Push_camp_spends FROM snitch_db.maplemonk.CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Push Notification\' GROUP BY 1 ), push_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS push_jour_rev, SUM(Spends) AS push_jour_spends FROM snitch_db.maplemonk.JOURNEY_REPORTS_SUMMARY WHERE channel = \'Push Notification\' GROUP BY 1 ), SMS_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As sms_camp_rev, SUM(Spends) AS sms_camp_spends FROM snitch_db.maplemonk.CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Sms\' GROUP BY 1 ), SMS_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS sms_jour_rev, SUM(Spends) AS sms_jour_spends FROM snitch_db.maplemonk.JOURNEY_REPORTS_SUMMARY WHERE channel = \'Sms\' GROUP BY 1 ), WA_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As wa_camp_rev, SUM(Spends) AS wa_camp_spends FROM snitch_db.maplemonk.CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'WhatsApp\' GROUP BY 1 ), WA_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS wa_jour_rev, SUM(Spends) AS wa_jour_spends FROM snitch_db.maplemonk.JOURNEY_REPORTS_SUMMARY WHERE channel = \'WhatsApp\' GROUP BY 1 ), email_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As email_camp_rev, SUM(Spends) AS email_camp_spends FROM snitch_db.maplemonk.CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Email\' GROUP BY 1 ), email_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS email_jour_rev, SUM(Spends) AS email_jour_spends FROM snitch_db.maplemonk.JOURNEY_REPORTS_SUMMARY WHERE channel = \'email\' GROUP BY 1 ) SELECT a.*, Coalesce(b.push_camp_rev,0) as push_camp_rev, coalesce(x.push_jour_rev,0) as push_jour_rev, coalesce(c.sms_camp_rev,0) as sms_camp_rev, coalesce(c.sms_camp_spends,0) as sms_camp_spends, coalesce(y.sms_jour_rev,0) as sms_jour_rev, coalesce(y.sms_jour_spends,0) as sms_jour_spends, coalesce(d.wa_camp_rev,0) as wa_camp_rev, coalesce(d.wa_camp_spends,0) as wa_camp_spends, coalesce(z.wa_jour_rev,0) as wa_jour_rev, coalesce(z.wa_jour_spends,0) as wa_jour_spends, coalesce(e.email_camp_rev,0) as email_camp_rev, coalesce(w.email_jour_rev,0) as email_jour_rev FROM CTE a LEFT JOIN push_camp_data b on a.run_date = b.run_date LEFT JOIN push_jour_data x on a.run_date = x.run_date LEFT JOIN sms_camp_data c on a.run_date = c.run_date LEFT JOIN sms_jour_data y on a.run_date = y.run_date LEFT JOIN wa_camp_data d on a.run_date = d.run_date LEFT JOIN wa_jour_data z on a.run_date = z.run_date LEFT JOIN email_camp_data e on a.run_date = e.run_date LEFT JOIN email_jour_data w on a.run_date = w.run_date );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
